$BACKEND_URL = "http://localhost:5001/"for ($i=0; $i -lt 20; $i++) {    try {        $r = Invoke-WebRequest -UseBasicParsing $BACKEND_URL        if ($r.Content -match 'OK') {            Write-Host 'Backend is up!'            exit 0        }    } catch {}    Write-Host "Waiting for backend..."    Start-Sleep -Seconds 3}Write-Host 'Backend did not start in time'exit 1